            fn spans(self: *@This(), a: std.mem.Allocator, values: []const encoder.presentation_types.Span, owner: []const u8) !void {
                for (values) |span| {
                    try self.visible.appendSlice(a, span.text);
                    try self.visible.appendSlice(a, span.trail);
