        roots[index] = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/el-geiosi-{d}", .{ tmp.sub_path, index });
        var writer = try encoder.blob_builder.Writer.init(io, a, roots[index]); defer writer.deinit();
