                .{}, null, null, &.{}, null, &.{}, if (code.len == 0) null else .{ .heading = owner, .code = code }, codes.table_styles);
            return (try encoder.presentation_codec.decodeAlloc(a, payload, title, .language, .{ .heading = owner, .code = code })).entry;
        }
        const Scan = struct {
