                    }
                    if (span.kind == .link or span.kind == .external_link) {
                        for (targets, labels, 0..) |target, label, i| if (std.mem.eql(u8, span.target, target)) {
                            try std.testing.expectEqualStrings(label, span.text); self.hits[i] += 1;
