    defer images.deinit();
    const css = try F.file(metadata, "common.css");
    try F.hash(css, "6f5ee1ae1a12edee57f216d4de78d995dfaa6a20ae0b43e6dbca5aeb30748a7d");
    var styles = try encoder.table_style_profile.parseAlloc(a, css);
