    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, F.source, "<span class=\"API\" title=\"Sêndagô API\">"));
    try std.testing.expect(std.mem.startsWith(u8, F.raw, "={{Y|nl}}=\n=={{S|pandôo|nl}}=="));
