            .{ .target = "ἀκατασβέστως#Μεσαιωνικά ελληνικά (gkm)", .label = "ἀκατασβέστως" },
            .{ .target = "κατασβεστικός#Μεσαιωνικά ελληνικά (gkm)", .label = "κατασβεστικός" },
