        .{ "figure-sizing.raw.json", "e76d8c6ae06b5ee3af78d7b54bbb9143be1fd80212be30c1b4b093a04f277d8c" },
        .{ "figure-sizing.site.json", "e76d8c6ae06b5ee3af78d7b54bbb9143be1fd80212be30c1b4b093a04f277d8c" },
    }) |record| {
