    try std.testing.expect(std.mem.indexOf(u8, F.source, "[[Datei:Sr,38.jpg|mini|zentriert| 170px| [1] [[Amostra]] de ''estrôncio'']]") != null);
    try std.testing.expectEqual(@as(usize, 5), actual.entry.references.len);
    var scan: F.Scan = .{};
