    var figure_inputs198 = try RetainedFigureInputs198.init("ru", io, a, try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/normal-figure-inputs-ru", .{tmp.sub_path}), &ns);
    defer figure_inputs198.sizing.deinit();
