    for ([_][]const u8{ "WomanWav.wav", "en-us-woman.ogg", "En-uk-woman.ogg", "En-woman.ogg" }) |file|
        try std.testing.expectEqual(T.MediaKind.audio, scan.files.get(file) orelse return error.TestUnexpectedResult);
    for ([_][]const u8{
