            for (value.rows) |row| for (row.cells) |cell| {
                if (cell.blocks) |children| try self.blocks(a, children) else {
                    try self.spans(a, cell.spans);
                    if (cell.nested_table) |nested| try self.table(a, nested);
                }
            };
