    const reference = try std.mem.replaceOwned(u8, a, F.source, needle, ":w:fr:L’Etranger");
    var ns = try namespace_registry.Registry.init(a, @embedFile("testdata/ku-malper/namespace-registry.tsv")); defer ns.deinit();
